// Agente de Banco de Dados - Inicialização
// Especialista em: PostgreSQL, Supabase, Queries, Performance, Índices

const payload = $input.item.json.body || $input.item.json;

return [{
  json: {
    agent: {
      name: 'Agente de Banco de Dados',
      version: '1.0',
      specialization: ['PostgreSQL', 'Supabase', 'SQL', 'Queries', 'Performance', 'Índices', 'Locks'],
      role: 'Diagnóstico e resolução de problemas de banco de dados'
    },
    sessionId: payload.sessionId,
    timestamp: payload.timestamp,
    issues: payload.issues || [],
    context: payload.context || {},
    orchestratorDecision: payload.orchestratorDecision || {},
    status: 'analyzing'
  }
}];

// Agregar dados coletados para análise
const agentData = $('Inicializar Agente').item.json;
const connections = $('Verificar Conexões').item.json[0] || {};
const tableSizes = $('Verificar Tamanhos Tabelas').item.json || [];
const slowQueries = $('Verificar Queries Lentas').item.json || [];
const locks = $('Verificar Locks').item.json || [];

const collectedData = {
  connections: connections,
  tableSizes: tableSizes,
  slowQueries: slowQueries,
  locks: locks,
  hasIssues: {
    tooManyConnections: parseInt(connections.total_connections || 0) > 50,
    hasSlowQueries: slowQueries.length > 0,
    hasLocks: locks.length > 0,
    largeTables: tableSizes.some(t => parseFloat(t.size_bytes || 0) > 1073741824) // > 1GB
  }
};

return [{
  json: {
    ...agentData,
    collectedData: collectedData,
    readyForAnalysis: true
  }
}];

// Preparar prompt para Claude AI
const data = $input.item.json;
const promptTemplate = $env.PROMPT_DB_SPECIALIST || $env.PROMPT_INFRA_SPECIALIST || '';

// Substituir placeholders no prompt
let prompt = promptTemplate
  .replace(/\{\{issues\}\}/g, JSON.stringify(data.issues, null, 2))
  .replace(/\{\{context\}\}/g, JSON.stringify({
    ...data.context,
    collectedData: data.collectedData
  }, null, 2));

// Adicionar contexto do agente
prompt = `Você é o Agente de Banco de Dados do CredGestor, especializado em PostgreSQL e Supabase.\n\n` + prompt;

return [{
  json: {
    ...data,
    prompt: prompt,
    model: $env.LLM_MODEL || 'claude-3-5-sonnet-20241022'
  }
}];

